"""Core Fortitude (except unresolved translated Facade) and Blood Sorcery."""
import runpy
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('review-core-disciplines.py')))
add=base['add']
add('unswayable-mind','Unswayable Mind','Fortitude',1,[260],[
('Descrição','Resiste a encantos, coerção e artimanhas com calma ou obstinação sobrenatural.'),('Custo','Gratuito.'),('Sistema','Some Fortitude a todas as rolagens para resistir a coerção, intimidação, sedução ou outra tentativa de influenciá-lo contra a vontade. Também funciona contra poderes como Dominação e Presença.'),('Duração','Passiva.')],[
('Descrição','Resists charm, coercion and trickery with supernatural calm or stubbornness.'),('Custo','Free.'),('Sistema','Add Fortitude to all rolls resisting coercion, intimidation, seduction or other attempts to influence you against your will. Also works against powers such as Dominate and Presence.'),('Duração','Passive.')])
add('resilience','Resilience','Fortitude',1,[260],[
('Descrição','Resistência sobrenatural fortalece a capacidade de suportar ferimentos.'),('Custo','Gratuito.'),('Sistema','Adicione Fortitude à trilha de Vitalidade.'),('Duração','Passiva.')],[
('Descrição','Supernatural endurance increases the capacity to withstand injury.'),('Custo','Free.'),('Sistema','Add Fortitude to the Health track.'),('Duração','Passive.')])
add('enduring-beasts','Enduring Beasts','Fortitude',2,[260],[
('Descrição','Compartilha resistência com animais afetados por seu Animalismo, de enxames a grandes feras.'),('Custo','Gratuito e automático no próprio fâmulo; um Teste de Sangue para outros animais.'),('Parada','Vigor + Animalismo, Dificuldade 3, para animais que não sejam o próprio fâmulo.'),('Sistema','Cada animal recebe Vitalidade adicional igual à Fortitude do usuário. Fora o fâmulo, pode fortalecer um animal por ponto de margem. Ao terminar, remova primeiro caixas sem dano; a redução pode matar o animal.'),('Duração','Uma cena.')],[
('Descrição','Shares endurance with animals affected by the user’s Animalism, from swarms to large beasts.'),('Custo','Free and automatic on your own famulus; one Rouse Check for other animals.'),('Parada','Stamina + Animalism, Difficulty 3, for animals other than your own famulus.'),('Sistema','Each animal gains additional Health equal to the user’s Fortitude. Outside the famulus, fortify one animal per point of margin. When it ends, remove undamaged boxes first; the reduction can kill the animal.'),('Duração','One scene.')],{'Animalismo':1})
add('toughness','Toughness','Fortitude',2,[260,261],[
('Descrição','Ignora parte de ferimentos superficiais, sem proteger diretamente contra dano agravado.'),('Custo','Um Teste de Sangue.'),('Sistema','Subtraia Fortitude de todo dano superficial sofrido, antes de reduzir à metade. Essa subtração não pode reduzir o dano a menos de 1.'),('Duração','Uma cena.')],[
('Descrição','Ignores part of superficial injuries without directly protecting against Aggravated damage.'),('Custo','One Rouse Check.'),('Sistema','Subtract Fortitude from all Superficial damage suffered before halving it. This subtraction cannot reduce damage below 1.'),('Duração','One scene.')])
add('defy-bane','Defy Bane','Fortitude',3,[261],[
('Descrição','Resiste temporariamente a fogo, luz solar e outras fontes de dano agravado.'),('Custo','Um Teste de Sangue; pode renovar o poder esgotado com outro Teste de Sangue.'),('Parada','Raciocínio + Sobrevivência, Dificuldade 3, para ativar como reflexo ao sofrer dano agravado inesperado. Falha não ativa; sucesso exige pagar o Teste de Sangue.'),('Sistema','Converta dano agravado em superficial até um total igual à Fortitude por ativação durante a cena, não por ataque ou ferimento. O dano convertido não pode ser curado no restante da cena. Exemplo: Fortitude 3 pode converter 2 pontos num ataque e mais 1 depois, esgotando a proteção.'),('Duração','Uma cena ou até esgotar a proteção, o que ocorrer primeiro.')],[
('Descrição','Temporarily resists fire, sunlight and other sources of Aggravated damage.'),('Custo','One Rouse Check; an exhausted power can be renewed with another Rouse Check.'),('Parada','Wits + Survival, Difficulty 3, to activate reflexively against unexpected Aggravated damage. Failure does not activate it; success requires paying the Rouse Check.'),('Sistema','Convert Aggravated damage to Superficial up to a total equal to Fortitude per activation during the scene, not per attack or injury. Converted damage cannot be mended for the rest of the scene. For example, Fortitude 3 can convert 2 points from one attack and 1 later, exhausting protection.'),('Duração','One scene or until protection is exhausted, whichever comes first.')])
add('draught-endurance','Draught of Endurance','Fortitude',4,[261],[
('Descrição','O Sangue transmite temporariamente parte da Fortitude do doador, como Elegância Direto da Fonte transmite Celeridade.'),('Custo','Um Teste de Sangue.'),('Sistema','Beber diretamente uma quantidade equivalente a um Teste de Sangue concede Fortitude igual à metade da do doador, arredondada para baixo, e os mesmos poderes dele até esse nível.'),('Duração','Uma noite; para vampiros, até a próxima alimentação ou Fome 5.')],[
('Descrição','The Blood temporarily transmits part of the donor’s Fortitude, as Draught of Elegance transmits Celerity.'),('Custo','One Rouse Check.'),('Sistema','Drinking directly an amount equivalent to one Rouse Check grants Fortitude equal to half the donor’s rating, rounded down, and their same powers up to that level.'),('Duração','One night; for vampires, until the next feeding or Hunger 5.')])
add('flesh-marble','Flesh of Marble','Fortitude',5,[261],[
('Descrição','A pele ganha brilho de mármore e bloqueia golpes antes de romper-se momentaneamente e recompor-se.'),('Custo','Dois Testes de Sangue.'),('Sistema','Ignore a primeira fonte de dano físico de cada turno, inclusive fogo, mas não luz solar. Em caso de dúvida sobre a primeira fonte, o Narrador decide pela narrativa ou ignora-se a única fonte de maior dano daquele turno. Uma vitória crítica numa rolagem de ataque supera a proteção.'),('Duração','Uma cena.')],[
('Descrição','The skin gains a marble sheen and stops blows before briefly breaking and reforming.'),('Custo','Two Rouse Checks.'),('Sistema','Ignore the first source of physical damage each turn, including fire but not sunlight. If the first source is unclear, the Storyteller decides from the narrative or ignores the single greatest damage source that turn. A critical win on an attack roll overcomes the protection.'),('Duração','One scene.')])
add('prowess-pain','Prowess from Pain','Fortitude',5,[262],[
('Descrição','Ferimentos alimentam força e velocidade, em vez de apenas debilitarem o vampiro.'),('Custo','Um Teste de Sangue.'),('Sistema','Ignore penalidades de dados causadas por dano à Vitalidade, como Debilitação. Pode aumentar um Atributo Físico em 1 por nível de dano superficial ou agravado na trilha de Vitalidade, sem alterar características derivadas. Nenhum Atributo pode ultrapassar seu bônus de Impulso de Sangue + 6 por esse poder.'),('Exceções','Use o bônus de Impulso da tabela oficial corrigida. O exemplo do PDF cita Potência 3, Impulso 2 e limite 9, valores incompatíveis entre si. Pela tabela corrigida, Potência 3 concede Impulso 3, portanto o limite pela fórmula é 9.'),('Duração','Uma cena.')],[
('Descrição','Injuries fuel strength and speed instead of merely impairing the vampire.'),('Custo','One Rouse Check.'),('Sistema','Ignore dice penalties from Health damage, such as Impairment. May increase a Physical Attribute by 1 per Superficial or Aggravated damage level in the Health track without changing derived traits. No Attribute can exceed the Blood Surge bonus + 6 through this power.'),('Exceções','Use the corrected official Blood Surge table. The supplied PDF example gives Blood Potency 3, Surge 2 and a cap of 9, which are mutually inconsistent. The corrected table gives Potency 3 a Surge of 3, so the formula yields a cap of 9.'),('Duração','One scene.')])
add('taste-blood','A Taste for Blood','Feitiçaria de Sangue',1,[274],[
('Descrição','Provar uma gota de sangue revela traços do doador.'),('Custo','Gratuito.'),('Parada','Determinação + Feitiçaria de Sangue, Dificuldade 3.'),('Sistema','Coloque o sangue na língua e teste. Vitória revela Ressonância e intensidade do sangue humano; identifica mortal, carniçal, vampiro ou outra criatura sobrenatural, sem necessariamente dizer o tipo desta última. Vitae revela a Potência de Sangue relativa e a faixa de geração. Crítico revela Diablerie e geração com margem de erro de um nível; também identifica outro tipo sobrenatural se o usuário já o conhecer.'),('Duração','Não aplicável.')],[
('Descrição','Tasting a drop of blood reveals traits of its donor.'),('Custo','Free.'),('Parada','Resolve + Blood Sorcery, Difficulty 3.'),('Sistema','Place the blood on the tongue and roll. A win reveals human blood’s Resonance and intensity, and identifies mortal, ghoul, vampire or another supernatural creature without necessarily identifying that last type. Vitae reveals relative Blood Potency and generation range. A critical reveals diablerie and generation within one level of error; it also identifies another supernatural type if already familiar to the user.'),('Duração','Not applicable.')],aliases=['Taste for Blood'])
add('corrosive-vitae','Corrosive Vitae','Feitiçaria de Sangue',1,[274,275],[
('Descrição','Torna uma porção de Vitae corrosiva contra matéria inanimada, exceto carne não viva como a vampírica.'),('Custo','Um ou mais Testes de Sangue.'),('Sistema','Sem teste adicional de Habilidade. Concentre-se por um turno e faça o Sangue sair por ferida aberta, normalmente autoinfligida, derramando-o no objeto. Cada Teste de Sangue corrói aproximadamente 35 cm em todas as direções a partir do impacto, conforme a medida impressa no PDF fornecido. Leva cerca de cinco minutos, mais em metais como cobre ou ferro fundido. Ligas duras e aço ficam marcados e afinados; o Narrador decide se enfraquecem significativamente. Com tempo e Vitae, pode corroer correntes de algemas.'),('Duração','Não aplicável.')],[
('Descrição','Makes a portion of Vitae corrosive to inanimate matter, except unliving flesh such as vampire flesh.'),('Custo','One or more Rouse Checks.'),('Sistema','No additional Skill roll. Concentrate for one turn and force Blood through an open wound, usually self-inflicted, onto the object. Each Rouse Check corrodes approximately 35 cm in every direction from the impact, as printed in the supplied Portuguese PDF. Takes about five minutes, longer for metals such as copper or cast iron. Hard alloys and steel are scarred and thinned; the Storyteller decides whether significantly weakened. With time and Vitae, handcuff chains can be dissolved.'),('Duração','Not applicable.')])
add('extinguish-vitae','Extinguish Vitae','Feitiçaria de Sangue',2,[275],[
('Descrição','Coagula parte do Sangue de outro vampiro, tornando-o impotente para sustentar a não vida e elevando sua Fome.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Feitiçaria de Sangue contra Vigor + Autocontrole.'),('Sistema','Concentre-se por um turno e gesticule discretamente para um vampiro à vista. Vitória aumenta sua Fome em 1; crítico, em 2. Se puder ver o usuário, a vítima pode reconhecê-lo como agressor com Inteligência + Ocultismo contra Raciocínio + Subterfúgio.'),('Duração','Não aplicável.')],[
('Descrição','Coagulates part of another vampire’s Blood, making it unable to sustain unlife and increasing Hunger.'),('Custo','One Rouse Check.'),('Parada','Intelligence + Blood Sorcery opposed by Stamina + Composure.'),('Sistema','Concentrate for one turn and gesture subtly at a vampire in sight. A win increases their Hunger by 1; a critical by 2. If able to see the user, the victim can identify the aggressor with Intelligence + Occult opposed by Wits + Subterfuge.'),('Duração','Not applicable.')])
venom_pt='Concentre-se por um turno e faça Sangue sair por ferida aberta, normalmente autoinfligida. Cada Teste de Sangue produz em um turno veneno para uma lâmina de Armas Brancas ou uma boca cheia para cuspir. Cuspir exige Destreza + Atletismo, com esquiva como ataque à distância; contato por beijo também é possível. Beber o veneno diretamente da veia transmite seus efeitos, inclusive contra diableristas. É veneno de contato que se perde em líquidos e é viscoso demais para seringa: não envenena bebidas nem é injetado por mordida. Flechas e balas levam quantidade insuficiente; dura pouco demais para preparar balas ocas.'
venom_en='Concentrate for one turn and force Blood through an open wound, usually self-inflicted. Each Rouse Check produces in one turn enough venom for a Melee blade or a mouthful to spit. Spitting uses Dexterity + Athletics and can be dodged as a ranged attack; contact through a kiss is also possible. Drinking directly from the vein transmits its effects, including against diablerists. It is a contact poison that dissipates in liquids and is too viscous for a syringe: it cannot poison drinks or be injected by a bite. Arrows and bullets carry too little; it lasts too briefly to prepare hollow bullets.'
add('scorpions-touch','Scorpion’s Touch','Feitiçaria de Sangue',3,[275],[
('Descrição','Transforma o Sangue em veneno paralisante para mortais e prejudicial a vampiros.'),('Custo','Um ou mais Testes de Sangue.'),('Parada','Após acertar o ataque envenenado, Força + Feitiçaria de Sangue contra Vigor + Ocultismo; vampiros podem substituir Ocultismo por Fortitude.'),('Sistema',venom_pt+' Uma vitória no conflito do veneno causa a margem em dano agravado à Vitalidade de mortais e superficial não reduzido à metade em vampiros. Mortal que sofra ao menos 1 dano cai inconsciente.'),('Duração','O veneno permanece ativo por uma cena.')],[
('Descrição','Transforms Blood into venom that paralyzes mortals and hinders vampires.'),('Custo','One or more Rouse Checks.'),('Parada','After a poisoned attack hits, Strength + Blood Sorcery opposed by Stamina + Occult; vampires may replace Occult with Fortitude.'),('Sistema',venom_en+' Winning the venom contest inflicts the margin as Aggravated Health damage on mortals and unhalved Superficial damage on vampires. A mortal suffering at least 1 damage falls unconscious.'),('Duração','The venom remains active for one scene.')],aliases=["Scorpion's Touch"])
add('blood-potency','Blood of Potency','Feitiçaria de Sangue',3,[275],[
('Descrição','Concentra o Sangue para aumentar temporariamente sua Potência.'),('Custo','Um Teste de Sangue.'),('Parada','Determinação + Feitiçaria de Sangue, Dificuldade 2 + Potência de Sangue atual.'),('Sistema','Vitória aumenta a Potência em 1; crítico, em 2. Pode ultrapassar o limite de Potência da geração enquanto durar.'),('Duração','A linha de Duração do PDF diz “Uma cena ou uma noite”; o parágrafo de Sistema diz “naquela cena”. A divergência é preservada para consulta à fonte, sem fixar uma duração alternativa automaticamente.')],[
('Descrição','Concentrates the Blood to temporarily increase Blood Potency.'),('Custo','One Rouse Check.'),('Parada','Resolve + Blood Sorcery, Difficulty 2 + current Blood Potency.'),('Sistema','A win increases Potency by 1; a critical by 2. May exceed the generation’s Blood Potency limit while active.'),('Duração','The supplied PDF’s Duration line says “one scene or one night”; its System paragraph says “for that scene.” This discrepancy is preserved for source consultation, without automatically selecting an alternative duration.')])
add('theft-vitae','Theft of Vitae','Feitiçaria de Sangue',4,[276],[
('Descrição','Abre misticamente uma artéria de mortal e leva o jato de sangue até a boca do usuário, subjugando-o como no Beijo. A ferida se fecha ao terminar, mesmo se a vítima morrer; o uso visível pode violar a Máscara.'),('Custo','Um Teste de Sangue.'),('Parada','Raciocínio + Feitiçaria de Sangue contra Raciocínio + Ocultismo.'),('Sistema','Acene para mortal à vista e vença o conflito para alimentar-se do outro lado do aposento. Proteção que cubra o corpo inteiro, como traje contra riscos químicos e biológicos, retém o sangue dentro do traje enquanto o alvo fica em êxtase. O usuário não pode fazer outra ação enquanto se alimenta. A alimentação ocorre ao dobro da velocidade normal, ou triplo num crítico.'),('Duração','Uma alimentação.')],[
('Descrição','Mystically opens a mortal artery and draws the blood stream into the user’s mouth, subduing the victim as with the Kiss. The wound closes when it ends even if the victim dies; visible use may violate the Masquerade.'),('Custo','One Rouse Check.'),('Parada','Wits + Blood Sorcery opposed by Wits + Occult.'),('Sistema','Gesture at a mortal in sight and win the contest to feed across the room. Full-body protection such as a chemical or biological hazard suit keeps the blood inside while the target experiences ecstasy. The user can take no other action while feeding. Feeding occurs at twice normal speed, or three times on a critical.'),('Duração','One feeding.')])
add('cauldron-blood','Cauldron of Blood','Feitiçaria de Sangue',5,[276],[
('Descrição','Ferve o sangue dentro das veias da vítima, causando dor e destruição extremas.'),('Custo','Um Teste de Sangue e uma ou mais Máculas.'),('Parada','Determinação + Feitiçaria de Sangue contra Autocontrole + Ocultismo; vampiros podem substituir Ocultismo por Fortitude.'),('Sistema','Pague o custo e toque a vítima, com Destreza + Atletismo em combate ou situação semelhante. Cada ponto de margem do conflito causa 1 dano agravado. Mortal que sofre ao menos 1 dano morre. Vampiros ganham 1 Fome por dano causado, até Fome 5.'),('Duração','Um turno.')],[
('Descrição','Boils blood within the victim’s veins, causing extreme pain and destruction.'),('Custo','One Rouse Check and one or more Stains.'),('Parada','Resolve + Blood Sorcery opposed by Composure + Occult; vampires may replace Occult with Fortitude.'),('Sistema','Pay the cost and touch the victim, using Dexterity + Athletics in combat or similar circumstances. Each point of contest margin inflicts 1 Aggravated damage. A mortal suffering at least 1 damage dies. Vampires gain 1 Hunger per damage inflicted, up to Hunger 5.'),('Duração','One turn.')])
add('baals-caress','Baal’s Caress','Feitiçaria de Sangue',5,[275,276],[
('Descrição','Transforma o Sangue em veneno letal para mortais e Membros, usando o processo e as restrições de Picada de Escorpião.'),('Custo','Um ou mais Testes de Sangue.'),('Parada','Após acertar, Força + Feitiçaria de Sangue contra Vigor + Ocultismo; vampiros podem substituir Ocultismo por Fortitude.'),('Sistema',venom_pt+' Vitória no conflito do veneno causa a margem em dano agravado à Vitalidade tanto em mortais quanto em vampiros. Mortal que sofra ao menos 1 dano morre instantaneamente. Se causar dano agravado a vampiro, repita o conflito; outra vitória faz a vítima entrar em Torpor na próxima vez que dormir.'),('Duração','O veneno permanece ativo por uma cena.')],[
('Descrição','Transforms Blood into venom lethal to mortals and Kindred, using Scorpion’s Touch’s process and restrictions.'),('Custo','One or more Rouse Checks.'),('Parada','After hitting, Strength + Blood Sorcery opposed by Stamina + Occult; vampires may replace Occult with Fortitude.'),('Sistema',venom_en+' Winning the venom contest inflicts the margin as Aggravated Health damage on both mortals and vampires. A mortal suffering at least 1 damage dies instantly. If a vampire takes Aggravated damage, repeat the contest; another win puts the victim into torpor the next time they sleep.'),('Duração','The venom remains active for one scene.')],aliases=["Baal's Caress"])
print('16 additional Core powers reviewed; Fortify the Inner Facade remains pending clarification')
